=<!doctype html>
<html lang="pt-BR">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Emissão de documentos</title>
<style>:root { --cor: {{ $json.cor }}; } {{ $json.css }}
.doc { display: flex; align-items: center; gap: 12px; padding: 12px 0; border-top: 1px solid #ebe9f2; }
.doc > div { flex: 1; min-width: 0; }
.doc strong { display: block; }
.doc span { color: #6b6880; font-size: .88rem; }
.selo { font-size: .75rem; font-weight: 600; padding: 2px 8px; border-radius: 99px; margin-left: 6px; }
.selo.ativo { background: #e6f4ea; color: #1d6b3f; } .selo.outro { background: #fdecea; color: #b3261e; }
.aviso { color: #b3261e; font-size: .85rem; }
.doc input { width: 20px; height: 20px; accent-color: var(--cor); flex: none; }
.doc .vazio { width: 20px; flex: none; }
.botoes { display: flex; gap: 8px; flex-wrap: wrap; }
.acoes { display: flex; gap: 8px; align-items: center; }
.partilha { position: relative; }
.partilha summary { list-style: none; cursor: pointer; }
.partilha summary::-webkit-details-marker { display: none; }
.partilha > div { position: absolute; right: 0; top: calc(100% + 6px); z-index: 5; width: min(340px, 86vw); display: flex; flex-direction: column; gap: 8px; background: #fff; border: 1px solid #ebe9f2; border-radius: 10px; padding: 12px; box-shadow: 0 6px 20px rgba(0,0,0,.12); }
.partilha textarea { width: 100%; box-sizing: border-box; font: inherit; font-size: .85rem; border: 1px solid #ebe9f2; border-radius: 6px; padding: 8px; resize: none; }
.partilha small { color: #6b6880; font-size: .78rem; }
.btn.perigo { background: #fff; color: #b3261e; border: 1px solid #b3261e; }
.btn.perigo.cheio { background: #b3261e; color: #fff; }
.revogar fieldset { border: 0; padding: 0; margin: 0; display: grid; gap: 6px; }
.revogar label { display: flex; gap: 8px; align-items: center; font-size: .9rem; color: inherit; }
.revogar input[type=radio], .revogar input[type=checkbox] { width: 18px; height: 18px; accent-color: #b3261e; }
.doc .motivo { display: block; color: #b3261e; font-size: .8rem; }
@media (max-width: 560px) { .acoes { width: 100%; flex-wrap: wrap; } .acoes > .btn, .partilha { flex: 1; } .partilha[open] { flex-basis: 100%; } .partilha summary { width: 100%; text-align: center; } .partilha > div { position: static; width: 100%; margin-top: 8px; box-shadow: none; } }
@media (max-width: 560px) { .doc { flex-wrap: wrap; } .doc .btn, .doc .aviso { width: 100%; text-align: center; } .botoes .btn { flex: 1; text-align: center; } }
</style>
</head>
<body>
<header class="topo"><div>{{ $json.logo_url ? '<img src="' + $json.logo_url + '" alt="">' : '' }}<b>Emissão de documentos</b><small>{{ $json.email }}</small></div></header>
<main>
{{ $json.erro ? '<div class="erro">' + $json.erro + '</div>' : '' }}
{{ $json.lote ? '<div class="ok"><span><strong>' + $json.lote.total + ' documentos cadastrados.</strong></span><span class="botoes">' + $json.lote.zips.map(z => '<a class="btn" href="' + z.href + '">' + z.rotulo + '</a>').join('') + '</span></div>' : '' }}
{{ $json.revogado ? '<div class="ok"><span><strong>Documento revogado:</strong> ' + $json.revogado.nome + '. A validação já mostra que ele não é mais válido.</span></div>' : '' }}
{{ $json.criado ? '<div class="ok"><span><strong>Documento cadastrado:</strong> ' + $json.criado.nome + '</span><a class="btn" href="' + $json.criado.href + '">Baixar PDF</a></div>' : '' }}
<div class="card">
  <div class="barra"><h1>Documentos ({{ $json.docs.length }})</h1><span class="botoes"><button class="btn claro" type="submit" form="sel">Baixar marcados (ZIP)</button><a class="btn claro" href="?importar">Importar CSV</a><a class="btn" href="?novo">+ Novo documento</a></span></div>
  <p class="muted">Os mais recentes primeiro. O PDF é gerado na hora, a partir da planilha. Para baixar vários de uma vez, marque até {{ $json.limite_zip }} e use "Baixar marcados (ZIP)".</p>
  <form id="sel" method="get" action="">
  {{ $json.docs.map(d => `<div class="doc">${d.id && d.ativo ? `<input type="checkbox" name="zip" value="${d.id}" aria-label="Marcar ${d.nome}">` : '<span class="vazio"></span>'}<div><strong>${d.nome}</strong><span>${[d.tipo, d.curso, d.data].filter(Boolean).join(' · ')}</span><span class="selo ${d.ativo ? 'ativo' : 'outro'}">${d.status}</span>${d.revogacao ? `<span class="motivo">Revogado ${d.revogacao}</span>` : ''}</div>${d.problema ? `<span class="aviso">${d.problema}</span>` : `<span class="acoes">${d.ativo ? `<a class="btn" href="${d.href}">Baixar PDF</a>` : ''}${d.compartilhar ? `<details class="partilha"><summary class="btn claro">Compartilhar</summary><div><textarea readonly rows="11" aria-label="Texto para enviar ao aluno">${d.compartilhar.texto}</textarea><span class="botoes"><a class="btn" href="${d.compartilhar.whatsapp}" target="_blank" rel="noopener noreferrer">WhatsApp</a><a class="btn claro" href="${d.compartilhar.email}">E-mail</a></span><small>Ou toque no texto, copie e cole em outro aplicativo.</small></div></details>` : ''}${d.revogar ? `<details class="partilha revogar"><summary class="btn perigo">Revogar</summary><div><strong>Revogar este documento?</strong><small>A validação passa a mostrar "Este documento não é mais válido". Para desfazer, só pela planilha.</small><fieldset><legend><small>Motivo</small></legend>${d.revogar.motivos.map(m => `<label><input type="radio" name="motivo" value="${m.valor}" form="rev-${d.revogar.id}" required> ${m.nome}</label>`).join('')}</fieldset><textarea name="detalhe" form="rev-${d.revogar.id}" rows="3" maxlength="300" placeholder="Justificativa (obrigatória em Outro)"></textarea><label><input type="checkbox" name="confirmo" value="sim" form="rev-${d.revogar.id}" required> Confirmo a revogação</label><button class="btn perigo cheio" type="submit" form="rev-${d.revogar.id}">Revogar documento</button></div></details>` : ''}</span>`}</div>`).join('') }}
  </form>
  {{ $json.docs.filter(d => d.revogar).map(d => `<form id="rev-${d.revogar.id}" method="post" action=""><input type="hidden" name="revogar" value="${d.revogar.id}"><input type="hidden" name="csrf" value="${$json.csrf}"></form>`).join('') }}
</div>
</main>
</body>
</html>
